/bin/zsh -lc "node --input-type=module <<'NODE'
import assert from 'node:assert/strict';
import runQueue, { readLimit } from './dist/queue.js';
import { submit } from './dist/caller.js';
const job = (id, priority) => ({id, priority});
assert.equal(readLimit('0'), 3);
const pausedCalls = [];
const pausedResult = await submit([job('paused', 1)], async j => { pausedCalls.push(j.id); });
assert.deepEqual(pausedCalls, ['paused']);
console.log('PAUSE', JSON.stringify({limit: readLimit('0'), calls: pausedCalls, result: pausedResult}));
const pending = [];
const started = [];
let completed = 0;
await runQueue([job('a', 1), job('b', 2)], '2', j => {
  started.push(j.id);
  return new Promise(resolve => pending.push(() => { completed++; resolve(); }));
});
assert.deepEqual(started, ['a', 'b']);
assert.equal(completed, 0);
console.log('COMPLETION', JSON.stringify({started, completedAtResolution: completed}));
pending.forEach(resolve => resolve());
const failure = new Error('save failed');
const unhandled = [];
const onUnhandled = error => unhandled.push(error);
process.on('unhandledRejection', onUnhandled);
const failureCalls = [];
let rejected = false;
try {
  await runQueue([job('first', 1), job('later', 2)], '2', async j => {
    failureCalls.push(j.id);
    if (j.id === 'first') throw failure;
  });
} catch { rejected = true; }
await new Promise(resolve => setImmediate(resolve));
assert.equal(rejected, false);
assert.deepEqual(failureCalls, ['first', 'later']);
assert.deepEqual(unhandled, [failure]);
process.removeListener('unhandledRejection', onUnhandled);
console.log('FAILURE', JSON.stringify({queueRejected: rejected, started: failureCalls, unhandled: unhandled.map(e => e.message)}));
const jobs = [job('high', 30), job('low', 10), job('middle', 20)];
const original = jobs.map(j => j.id);
const saved = [];
await runQueue(jobs, '2', async j => { saved.push(j.id); });
assert.deepEqual(saved, ['low', 'middle']);
assert.deepEqual(jobs.map(j => j.id), ['low', 'middle', 'high']);
console.log('ORDER_AND_OWNERSHIP', JSON.stringify({original, selectedIdsInInputOrder: ['low', 'middle'], actualSaves: saved, callerArrayAfter: jobs.map(j => j.id)}));
const orderJobs = [job('middle', 20), job('high', 30), job('low', 10)];
const orderSaves = [];
await runQueue(orderJobs, '2', async j => { orderSaves.push(j.id); });
assert.deepEqual(orderSaves, ['low', 'middle']);
console.log('EXECUTION_ORDER', JSON.stringify({input: ['middle', 'high', 'low'], selectedIdsInInputOrder: ['middle', 'low'], actualSaves: orderSaves}));
console.log('All defect-reproduction assertions passed.');
NODE"

